 const aync = "{\"parsed\":{\"_path\":\"/interviewer/aync\",\"_dir\":\"interviewer\",\"_draft\":false,\"_partial\":false,\"_locale\":\"\",\"title\":\"异步\",\"description\":\"javascript 引擎负责解析，执行 javascript 代码，但它并不能单独运行，通常都得有一个宿主环境，一般如浏览器或 Node 服务器，前文说到的单线程是指在这些宿主环境创建单一线程，提供一种机制，调用 javascript 引擎完成多个 javascript 代码块的调度，这种机制就称为事件循环（ Event Loop ）\",\"layout\":\"article\",\"img\":\"app-site/img/action-scope.jpg\",\"header\":\"app-site/img/action-scope-header.jpg\",\"date\":\"2023-04-01 12:12:12\",\"category\":\"面试\",\"tags\":[\"面试\",\"异步\",\"javascript\"],\"body\":{\"type\":\"root\",\"children\":[{\"type\":\"element\",\"tag\":\"h4\",\"props\":{\"id\":\"关于事件循环流程分解如下\"},\"children\":[{\"type\":\"text\",\"value\":\"关于事件循环流程分解如下：\"}]},{\"type\":\"element\",\"tag\":\"ul\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"宿主环境为javascript 创建线程时，会创建堆 (heap) 和栈 (stack) ，堆内存储 javascript 对象，栈内存储执行上下文；\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"栈内执行上下文的同步任务按序执行，执行完即退栈，而当异步任务执行时，该异步任务进入等待状态（不入栈），同时通知线程：当触发该事件时（或该异步操作响应返回时），需向消息队列插入一个事件消息；\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"当事件触发或响应返回时，线程向消息队列插入该事件消息（包含事件及回调）；\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"当栈内同步任务执行完毕后，线程从消息队列取出一个事件消息，其对应异步任务（函数）入栈，执行回调函数，如果未绑定回调，这个消息会被丢弃，执行完任务后退栈；\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"当线程空闲（即执行栈清空）时继续拉取消息队列下一轮消息（next tick ，事件循环流转一次称为一次 tick ）。\"}]}]},{\"type\":\"element\",\"tag\":\"h2\",\"props\":{\"id\":\"并发模型与事件循环-concurrency-model-and-the-event-loop\"},\"children\":[{\"type\":\"text\",\"value\":\"并发模型与事件循环 Concurrency model and the event loop\"}]},{\"type\":\"element\",\"tag\":\"h3\",\"props\":{\"id\":\"浏览器中的事件循环\"},\"children\":[{\"type\":\"text\",\"value\":\"浏览器中的事件循环\"}]},{\"type\":\"element\",\"tag\":\"ul\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"函数的执行顺序实现：函数调用栈、任务队列(task queue)\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"一个线程中，事件循环是唯一，任务队列可以拥有多个\"}]}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"strong\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"任务队列：\"}]}]},{\"type\":\"element\",\"tag\":\"ul\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"宏任务macro-task：\\n\"},{\"type\":\"element\",\"tag\":\"ul\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"script(整体代码)\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"setTimeout\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"setInterval\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"setImmediate\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"I/O\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"UI render\"}]}]}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"微任务micro-task：\\n\"},{\"type\":\"element\",\"tag\":\"ul\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"process.nextTick\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"Promise\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"Async/Await(实际就是promise)\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"MutationObserver(html5新特性)\"}]}]}]}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"先执行宏任务，然后执行该宏任务产生的微任务，若微任务在执行过程中产生了新的微任务，则继续执行微任务，微任务执行完毕后，再回到宏任务中进行下一轮循环\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"node 11:\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"输入数据阶段(incoming data)\\n->\\n轮询阶段(poll)\\n->\\n检查阶段(check)\\n->\\n关闭事件回调阶段(close callback)\\n->\\n定时器检测阶段(timers)\\n->\\nI/O事件回调阶段(I/O callbacks)\\n->\\n闲置阶段(idle, prepare)\\n->\\n轮询阶段(poll)\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"node io密集型\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"http无状态协议\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"webpack  gulp\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"a\",\"props\":{\"href\":\"https://juejin.cn/post/6844904100195205133\",\"rel\":[\"nofollow\"]},\"children\":[{\"type\":\"text\",\"value\":\"https😕/juejin.cn/post/6844904100195205133\"}]}]}],\"toc\":{\"title\":\"\",\"searchDepth\":2,\"depth\":2,\"links\":[{\"id\":\"并发模型与事件循环-concurrency-model-and-the-event-loop\",\"depth\":2,\"text\":\"并发模型与事件循环 Concurrency model and the event loop\",\"children\":[{\"id\":\"浏览器中的事件循环\",\"depth\":3,\"text\":\"浏览器中的事件循环\"}]}]}},\"_type\":\"markdown\",\"_id\":\"content:interviewer:aync.md\",\"_source\":\"content\",\"_file\":\"interviewer/aync.md\",\"_stem\":\"interviewer/aync\",\"_extension\":\"md\"},\"hash\":\"neOA2w5T2B\"}";

